<?php
// ابدأ الجلسة (يجب أن يكون أول شيء)
session_start();

// --- هذا هو "الحارس" ---

// 1. هل المستخدم مسجل دخوله؟ (هل متغير الجلسة user_id موجود؟)
// 2. هل دور المستخدم هو "admin"؟
if ( !isset($_SESSION['user_id']) || $_SESSION['role'] !== 'admin' ) {
    
    // إذا لم يكن مسجل دخوله، أو كان مسجلاً ولكنه ليس "مدير" (مثل عميل يحاول فتح الرابط)
    
    // 1. (اختياري) امسح أي بيانات جلسة خاطئة قد تكون موجودة
    session_unset(); // إزالة متغيرات الجلسة
    session_destroy(); // تدمير الجلسة

    // 2. أعد توجيهه إلى صفحة تسجيل الدخول مع رسالة خطأ
    // (error=auth يعني "خطأ مصادقة")
    header("Location: login.php?error=auth");
    exit; // أوقف تنفيذ باقي الكود فوراً
}

// إذا وصل الكود إلى هنا، فهذا يعني أن المستخدم مسجل دخوله وهو "مدير".
// يمكنه رؤية محتوى الصفحة.
// يمكننا أيضاً تخزين بيانات المدير في متغيرات لسهولة الاستخدام
$admin_id = $_SESSION['user_id'];
$admin_name = $_SESSION['name'];

?>